// Moh2.cpp, the game's main module, as one unit: the DVD error task, the
// status screen, the shell and level loops (main), the per-frame game loop,
// level loading and restart, engine start-up (InitCORE), the render-list and
// screen helpers, the file's globals (scene, camera, fog, viewports, render
// list, pause, shell, fades, config, cheats and the field-mode screen) with
// their static initialiser, the embedded internal font, and the weak bodies of
// the scene-node interfaces that the file emits.
//
// The file was compiled with deferred inlining and RTTI on, so the functions
// are written in reverse image order (deferred emission reverses them back),
// small helpers (WaitRenderList, WaitScreen, SendRenderList) are inlined into
// their callers while still being emitted, and the class names, base lists and
// tables of CFadeOut, CFadeIn and the scene-node interfaces are the file's own.
// EndErrorText, LoadTheGame and RestartGame are kept out of line with
// '#pragma dont_inline' around their definitions (the original calls them).
// Function, global and class names come from the symbols; class layouts, the
// constructors' argument names, the error-screen helper ErrorLine, the frame
// delta helper GetFrameDelta and LoadTheGame's GetLevel are inferred.
// InternalFont is the original data (an FNTG font image).

