char* pInternalFont = InternalFont;
CFont* errorFont;
int FontLoaded;
int resethappend;
int DisableReset;
int DisableResetEntirley;
int QueueReset;

inline void ErrorLine(float y, const char* text) {
    g_screen.SetClearColor(CColor(0, 0, 0, 128));
    g_screen.SetClear(true);
    errorFont->SetColor(CColor(80, 18, 18, 128));
    errorFont->DrawTextCentered(y * g_screen.m_heightScale, text);
    errorFont->DrawTextCentered(y * g_screen.m_heightScale, text);
}

int MohDVDErrorTask(int, int) {
    int error = 0;
    static int softwareresetcheckstarted = 0;
    static int softwareresetstarttime = 0;
    if (!FontLoaded) {
        errorFont = new CFont(pInternalFont, (ERenderPriority)111);
        FontLoaded = 1;
    }
    int status;
    do {
        if (OSGetResetButtonState() && resethappend < 2 && !DisableResetEntirley) {
            resethappend = 1;
        } else if (resethappend == 1) {
            resethappend = 2;
        } else if ((resethappend > 1 && resethappend < 60) || QueueReset) {
            if (DisableReset) {
                QueueReset = 1;
            } else {
                QueueReset = 0;
                resethappend++;
            }
        } else if (resethappend >= 60) {
            PADRecalibrate(0xf0000000);
            GXDrawDone();
            VISetBlack(1);
            VIFlush();
            VIWaitForRetrace();
            OSResetSystem(1, 1, 0);
            resethappend = 0;
        } else {
            resethappend = 0;
        }
        if ((gPadStatus[0].button == 0x1600 || gPadStatus[1].button == 0x1600 || gPadStatus[2].button == 0x1600 ||
             gPadStatus[3].button == 0x1600) &&
            !DisableResetEntirley) {
            if (!softwareresetcheckstarted) {
                softwareresetstarttime = TIMER_gettick();
                softwareresetcheckstarted = 1;
            } else {
                float limit = 0.5f * (float)TIMER_getfrequency();
                if ((float)(int)(TIMER_gettick() - softwareresetstarttime) > limit && resethappend == 0)
                    resethappend = 1;
            }
        } else {
            softwareresetcheckstarted = 0;
            softwareresetstarttime = 0;
        }
        status = DVDGetDriveStatus();
        if (resethappend < 2) {
            switch (status) {
            case 5:
                g_screen.SetClear(true);
                ErrorLine(195.0f, "The Disc Cover is open.");
                ErrorLine(225.0f, "If you want to continue the game, please close the Disc Cover.");
                EndErrorText();
                error = 1;
                break;
            case 6:
                ErrorLine(180.0f, "This is not the Medal of Honor Frontline Game Disc.");
                ErrorLine(210.0f, "Please insert the Medal of Honor Frontline");
                ErrorLine(240.0f, "Game Disc.");
                EndErrorText();
                error = 1;
                break;
            case 4:
                g_screen.SetClear(true);
                ErrorLine(180.0f, "Please insert the");
                ErrorLine(210.0f, "Medal of Honor Frontline");
                ErrorLine(240.0f, "Game Disc.");
                EndErrorText();
                error = 1;
                break;
            case 11:
                g_screen.SetClear(true);
                ErrorLine(170.0f, "The Game Disc could not be read.");
                ErrorLine(200.0f, "Please read the");
                ErrorLine(230.0f, "Nintendo GameCube\x99 Instruction Booklet");
                ErrorLine(260.0f, "for more information.");
                EndErrorText();
                error = 1;
                break;
            case -1:
                error = 1;
                g_screen.SetClear(true);
                ErrorLine(170.0f, "An error has occurred.");
                ErrorLine(200.0f, "Turn off the power and refer to the");
                ErrorLine(230.0f, "Nintendo GameCube\x99 Instruction Booklet");
                ErrorLine(260.0f, "for further instructions.");
                EndErrorText();
                break;
            case 0:
                error = 0;
                DisableResetEntirley = 0;
                break;
            }
        }
        if (error || resethappend > 0) {
            g_inputMgr.ResetActuatorState(0);
            g_inputMgr.Update(1.0f);
        }
    } while (resethappend > 2 || error || status == -1);
    return 0;
}
